        CALL PROWERKA ;ищем central directory, достаём таблицу файлов в CAT, заполняем переменные про файл
                if 1==0        LD A,(SKIPING)        OR A        JR Z,NOSKIP1        LD HL,T_KEY1        LD (MODECAT+1),HL
        CALL VIEWCAT        LD A,#4F        LD (TEKATR+1),A        LD HL,0        LD DE,#440        CALL RAMKA        LD HL,T6935        CALL PRINTS_        LD HL,T6935_        CALL PRINTS_        LD HL,#400        LD DE,#C40        CALL RAMKANOSKIP1
        endif
                ;LD A,1        ;LD (D_INST),A ;это было для инициализации TR-DOS после смены диска        LD DE,0LEN_KOM=$-2        LD A,D        OR E        JR Z,PR700        LD HL,#4000        OR A        SBC HL,DE        JR C,PR700 ;комментарий > 0x4000?        EX DE,HL        LD DE,0 ;size of central directorySM1=$-2        LD C,0SM2=$-1        LD HL,(SME_ML) ;start of central directory        LD A,(SME_ST)        ADD HL,DE        ADC A,C        LD DE,#16       LD C,0        ADD HL,DE        ADC A,C        LD IX,BUFER        LD DE,(LEN_KOM) ;комментарий может быть до 0x4000 (реально формат позволяет больше)        CALL READ        ;LD HL,TEXT20        ;CALL PRINTS_
        if 1==0        LD A,0MEN=$-1        OR A        JR Z,NM1        CALL INS_DESTNM1     LD A,(DESTIN)        CP "*"        JR NZ,$+5        LD A,(SOURCE)        SUB #41        LD C,1        CALL TRDOS        LD C,#18        CALL TRDOS        LD HL,FNAME1        LD DE,23773        LD BC,9        LDIR         LD HL,BUFER        LD DE,(LEN_KOM)        LD C,#B        CALL TRDOS        LD A,(MEN)        OR A       JR Z,PR700       CALL INS_SOURC        endif
PR700   
        ;LD HL,TEXT21        ;CALL PRINTS_
                LD HL,0KOL_F=$-2        ;XOR A        ;LD IX,T_BUF        ;CALL DS100        ;LD HL,T_KOL_F        ;CALL PRINTS_nextfile           ;LD A,5           ;call ON_BANK 
        
        LD HL,0 ;start of central directory (сделал, чтобы он обновлялся с каждым новым файлом)SME_ML=$-2        LD A,0SME_ST=$-1        ;EXA 
        if 1==0        LD BC,(KOL_F)        LD A,C        LD (F_KOL),AZ6013   PUSH BC        LD A,0F_KOL=$-1        SUB C        INC A        LD (NUM_F),A ;номер файла        endif
                if 1==0        PUSH HL        LD HL,#71A ;координаты        LD (COR),HL        LD B,13CLS1    PUSH BC        LD A,#20        CALL PR        POP BC        DJNZ CLS1        POP HL        endif        ;EXA         LD B,A ;SME_ST        LD IX,BUFER        LD DE,#2E        LD C,41        CALL READ ;читаем описатель одного файла
        if 1==0        EXX         LD A,(BUFER+#24)        LD HL,CODE       BIT 0,A       JR Z,LL20        LD HL,TEXTLL20    LD DE,T_TYPE        LD BC,4        LDIR         EXX 
        endif        LD A,B ;SME_ST        ADD HL,DE        ADC A,D ;перемещаем указатель на имя        LD DE,(Z6638) ;file name length        LD B,A        LD IX,Z664A        CALL READ ;читаем имя файла;Z664A=ИMЯ TEKУЩEГO ФAЙЛА B APXИBE        ADD IX,DE        LD (IX),0 ;кладём 0 в конец имени (получится ASCIIZ)        LD A,B        ADD HL,DE        ADC A,0 ;перемещаем указатель после имени        LD B,E       DEC D       INC D        JR Z,Z604D ;длина имени <256       LD B,0 ;длина имени >=256, считаем, что 256Z604D   LD DE,(Z663A) ;extra field length        ADD HL,DE       ADC A,0 ;пропускаем extra field        LD DE,(Z663C) ;file comment length        ADD HL,DE        ADC A,0 ;пропускаем file comment length       ld (SME_ML),hl       ld (SME_ST),a        ;сформировать filename        ld hl,Z664A        ld de,filename        call strcopy ;TODO create directory        ld hl,filename
        call prtext
        call prcrlf
        
        if 1==0
                LD HL,#5CE5        LD DE,T_PKT        LD B,3        CALL PROVERK        JR C,NX600        LD A,"C"        LD (#5CE5),A        LD A,(#5CDD)        CP "0"        JR C,$+6        CP ":"        JR NC,NX600        AND 7        OR #30        LD (#5CDD),ANX600
        endif
        
        if 1==0
        LD A,(SKIPING)       OR A        JR Z,NOSKIP       LD A,(NUM_F)       LD L,A        LD H,'MARKBUF       LD A,(HL)       AND A        JP Z,SKIPNOSKIP  
        endif
        if 1==0
        LD IX,T_TEK        LD HL,0NUM_F=$-2        CALL DS100        LD HL,T_FILE        CALL PRINTS_
        endif        ;LD HL,#71A ;координаты        ;LD (COR),HL        ;LD HL,T61F7        ;CALL PRINTS        ;LD A,#4F        ;LD (TEKATR+1),A        XOR A        LD HL,-1        LD (ML_CRC32),HL        LD (ST_CRC32),HL        LD HL,(Z6634)        OR H        OR L        LD (ML_LEN_ISH),HL;HL= МЛАДШИE БAЙTЫ ДЛИHЫ ИCXOДHOГO ФAЙЛA        LD HL,(Z6636)        OR H        OR L        LD (ST_LEN_ISH),HL;HL= CTAPШИE БAЙТЫ ДЛИНЫ ИCXOДHOГO ФAЙЛA        JP Z,SKIP; HУЛЕВАЯ ДЛИHA        ;LD A,L        ;LD HL,(ML_LEN_ISH)        ;LD IX,T_ORIG        ;CALL DES_        LD HL,T6628 ;file last modification time        LD DE,T6221        LD BC,8        LDIR ;??? TODO установить дату после распаковки        LD A,(T6624) ;flags        RRA         JR NC,Z60E3;ФAЙЛ 3AKOДИPOBAH        LD A,3        LD (FLAGS),A ;CRYPTEDZ60E3   LD HL,(T6626);T6626=METOД CЖATИЯ: 0:STORED, 8:DEFLATE, others unknown        LD A,H        OR A        JR NZ,Z60F1        OR L        JR Z,Z60FC        CP 8        JR Z,Z60FCZ60F1   ;LD HL,UNKNOWN        ;LD DE,T_METOD        ;LD BC,7        ;LDIR         LD A,2        LD (FLAGS),A ;UNKNOWN (число в A не должно совпадать с 0 или 8!)        ;JR UNK_Z60FC   
        if 1==0
        BIT 3,A        LD HL,STORED        JR Z,ST_        LD HL,DEFLATEST_     LD DE,T_METOD        LD BC,7        LDIR 
        endifUNK_    PUSH AF ;0:STORED, 8:DEFLATE, others unknown        ;LD HL,(Z6630)        ;LD A,(Z6632);A,HL= ДЛИHA CЖATOГO ФAЙЛА        ;LD (ML_PAC_LEN),HL        ;LD (ST_PAC_LEN),A
        
        if 1==0        LD IX,T_PACK        CALL DES_        LD B,4        LD HL,CRC_ISH+3        LD DE,T_CRCL100    LD A,(HL)        CALL HEX        DEC HL        DJNZ L100        CALL T_IND ;инициализация процентомера?
        LD HL,0 ;текущий размер файла для процентомера        LD (B1),HL        LD (B2),HL        endif        ;CALL DATA_COR ;печать даты?        ;LD HL,T_PACK_L        ;CALL PRINTS_
FLAGS=$+1        LD A,0;(FLAGS) ;2:UNKNOWN, 3:CRYPTED, other=OK (формируется выше)        ;LD HL,T_UNK        CP 2        JR Z,SK__        ;LD HL,T_CRYPT        CP 3;:JR Z,SK__;LD A,(SKIPING):OR A;JR Z,PROD10        JR NZ,PROD10SK__    ;CALL PRINTS_        ;CALL KEY10_        POP AF        JP SKIPPROD10  
        if 1==0
        LD HL,#5CE5        LD DE,T_TRD        LD B,3        CALL PROVERK        JR C,NXSCL        LD HL,TRDOBR        CALL PRINTS_KEY11   XOR A       LD (#5C08),A        EI         HALT        LD A,(#5C08)       OR A        JR Z,KEY11        CP "Y"        JR Z,nX601_        CP 13       JR NZ,NX601nX601_        XOR A        LD (MEN),A        LD A,(DESTIN)        CP "*"        JR Z,MEN100       LD A,(DESTIN)       LD L,A        LD A,(SOURCE)       CP L        JR NZ,MEN100       LD A,1        LD (MEN),AMEN100        LD A,#C3        LD (SAVE),A        LD HL,SAVETRD        LD (SAVE+1),HL        LD HL,0        LD (TRK_SECT),HL        JR NX602NXSCL        LD HL,#5CE5        LD DE,T_SCL        LD B,3        CALL PROVERK        JR C,NX601;EXTRACTING FROM SCL       IFN 1        LD HL,SCLOBR        CALL PRINTS_KEY11S  XOR A       LD (#5C08),A        EI         HALT        LD A,(#5C08)       OR A        JR Z,KEY11S        CP "Y"        JR Z,nX601_S        CP 13       JR NZ,NX601nX601_S        LD A,"S        LD (YESSCL),A       ELSE        LD A,#C3       LD (SAVE),A       LD HL,SAVESCL       LD (SAVE+1),HL       LD HL,0       LD (TRK_SECT),HL       JR NX602       ENDIF        ;NORMAL FILE (NOT TRD OR SCL)NX601   LD A,#3E        LD (SAVE),A        LD HL,#CD04        LD (SAVE+1),HL
       endif        
        if 1==0        LD A,(ST_LEN_ISH)        OR A        JR NZ,NX602        LD HL,(ML_LEN_ISH)       LD DE,#FF12       OR A       SBC HL,DE        JR NC,NX602        LD A,(#5CE5)        CP "$"        JR NZ,NX602        LD (HOB),ANX602   
        endif

        LD HL,(Z6646) ;Relative offset of local file header. This is the number of bytes between the start of the first disk on which the file occurs, and the start of the local file header. This allows software reading the central directory to locate the position of the file inside the ZIP file.        LD A,(Z6648)
        ;jr $;A,HL= CMEЩEHИE ДO ЛOKAЛЬНOГO 3AГОЛОBKA        LD IX,BUFER        LD DE,#1E        LD C,#29        LD B,A        CALL READ        XOR A        ADD HL,DE        ADC A,B        LD DE,(Z6636);DE= ДЛИНA ИMEHИ ФAЙЛA        ADD HL,DE        ADC A,0        LD DE,(Z6638);DE= ДOПOЛHИTEЛЬНOE ПOЛE ДЛИНЫ        ADD HL,DE        ADC A,0        ;LD (Z634C),HL ;текущая позиция чтения в файле        ;LD (Z634F),A;теперь физически установим указатель файла туда        ld d,0        ld e,a        ;ld hl,1        ;dehl=shift        ld a,(filehandle)        ld b,a        OS_SEEKHANDLE                call SAVECREATE               LD IY,DISKBUF+DISKBUFsz-1                ;LD HL,0        ;LD (T622D),HL        ;LD (T622E),HL        
;DEPACK       LD HL,0
       LD (U6546),HL ;сколько байт сохранить = текущий адрес в буфере
        POP BC ;0:STORED, 8:DEFLATE, others unknown        BIT 3,B        ;LD (inflateq_sp),SP ;??? TODO        CALL Z635E ;nz=INFLATING       ;LD A,(YESSCL)       ;CP "S       ;CALL Z,DESCLPP       ; XOR A       ;LD (YESSCL),A        ;LD (NO_HOB),A        ;LD (HOB),A        LD A,(CRC32_)        CP #C9        JR Z,SKIP        LD HL,ML_CRC32        LD DE,CRC_ISH        LD B,4Z6159   LD A,(DE)        XOR (HL)        INC HL,DE,AC1      JR NZ,crcerror;Z6164        DJNZ Z6159        JR SKIPcrcerror;Z6164;CRC ERROR        ;CALL E_CRC ;!!!!!!!!!!
        ld hl,tcrcerror
        call prtextSKIP         call SAVECLOSE        ld bc,(KOL_F)        cpi        ld (KOL_F),bc        jp pe,nextfileE_ZIP
