PROWERKA
        if 1==0
        LD A,#4F        LD (TEKATR+1),A        LD HL,#400        LD DE,#C40        CALL RAMKA        LD HL,FNAME        LD DE,T6927        LD BC,8        LDIR         LD A,"."        LD (DE),A        INC DE        LDI         LD A,(HL)        CP #20        JR C,NOEXN        INC HL        LD A,(HL)        DEC HL        CP #20        JR C,NOEXN        LDI         LDI         JR NOEXN+5NOEXN   LD A,#20        LD (DE),A        INC DE        LD (DE),A        LD HL,FNAME        LD DE,N_ARC        LD BC,8        LDIR        LD A,"."       LD (DE),A       INC DE       LDI        LD A,(HL)       CP #20       JR C,NOEHN       INC HL       LD A,(HL)       DEC HL       CP #20       JR C,NOEHN       LDI        LDI        JR NOEHN+5NOEHN  LD A,#20       LD (DE),A       INC DE       LD (DE),A        LD HL,T6918        CALL PRINTS_
        
        endif
                ;CALL F_OPEN        LD HL,CAT        LD DE,CAT+1        LD BC,#63F        LD (HL),0        LDIR ;TODO убрать        LD HL,CAT        LD (BUFCAT),HL;ПPOBEPKA APXИBA
;каталог лежит в конце файла, как до него добраться?
;Z66FA;a=??? после F_OPEN (!=0 разрешает искать назад -0x800 даже в маленьком файле любого размера) TODO
        LD A,(ST_FLEN)        LD HL,(ML_FLEN) ;ahl=длина файла        LD DE,#800         OR A         JR NZ,Z6727        LD A,H        CP 8        LD A,E;0        JR NC,Z6727 ;длина файла >=0x800, так что начнём поиск с длина файла-0x800        OR H        JR NZ,Z6714;длина файла < 0x100        LD A,L        CP #64        JR C,Z6780 ;длина файла < 0x64 - нет ни одного файла, ошибкаZ6714   PUSH HL        XOR A        LD HL,BUFER        LD DE,BUFER+1        LD (HL),A        LD BC,#7FF        LDIR ;очистили буфер, чтобы случайно не найти end of central directory не там        POP DEZ6723   LD L,A ;ищем в начале файла        LD H,A        JR _Z672AZ6727   SBC HL,DE        SBC A,E_Z672A   LD B,A        LD IX,BUFER        ;de=0x800        CALL LOAD_B ;поиск блока end of central directory        LD A,B        JR Z,Z6747 ;end of central directory        OR L        OR H        JR Z,Z6780 ;дошли до начала файла, а end of central directory не нашли        LD A,B        LD BC,#7EA ;смещаем указатель файла назад почти на 0x800        SBC HL,BC        SBC A,0        JR NC,_Z672A ;ищем назад        XOR A        JR Z6723 ;ищем в начале файлаZ6747;нашли end of central directory (ix = адрес этого блока в BUFER+)        PUSH IX        POP BC        ADD HL,BC       ADC A,0        LD BC,BUFER        SBC HL,BC       SBC A,0 ;ahl=смещение end of central directory в файле        LD (Z6896),HL ;текущее смещение в файле? TODO убрать        LD (Z6894),A        EX DE,HL        LD H,(IX+#11)        LD L,(IX+#10) ;offset of start of central directory;МЛАДШИЕ БAЙTЫ CMEЩEHИЯ HAЧAЛА ЦEHTPAЛЬHOГO KATAЛOГA        LD (SME_ML),HL        LD (IX+2),A ;???        LD A,(IX+#12) ;offset of start of central directory HSB;CTAPШИЙ БAЙT CMEЩЕНИЯ        LD (SME_ST),A        LD B,(IX+#D)        LD C,(IX+#C)        LD (SM1),BC ;size of central directory;BC=ДЛИНA ЦEHTPAЛЬHOЙ ДИPEKTOPИИ, МЛАДШИЕ БAЙТЫ        ADD HL,BC        ADC A,(IX+#E) ;s