1E        ADD HL,DE        LD (NAMEF3+1),HL        LD E,(IX+#1A)        LD D,(IX+#1B)        ADD HL,DE        LD DE,(BUFCAT)        PUSH DE,DE        LD A," "        LD B,11        LD (DE),A        INC DE        DJNZ $-2NAMEF3  LD DE,0NAMEF4  DEC HL        PUSH HL        AND A        SBC HL,DE        POP HL       JR NC,NAMEF5       EX DE,HL       DEC HL       JR NAMEF6NAMEF5  LD A,(HL)        CP "/"        JR NZ,NAMEF4NAMEF6  POP DE        INC HL        LD B,8NAMEF2  LD A,(HL)        INC HL        CP "."        JR Z,NAMEF1        LD (DE),A        INC DE        DJNZ NAMEF2        LD A,(HL)        INC HL        CP "."        JR NZ,$-4NAMEF1  POP DE        LD B,8        INC DE        DJNZ $-1       LD BC,3        LDIR         LD A,(IX+#16)        LD (DE),A        INC DE        LD A,(IX+#17)        LD (DE),A        INC DE        LD A,(IX+#18)        LD (DE),A        INC DE,DE,DE        EX DE,HL        LD (BUFCAT),HL        LD HL,#1E        LD A,(IX+#1B);A=СТАРШИЙ БAЙT ДЛИHЫ СMEHЫ ФAЙЛА        CP 2        JP NC,ERR_Z3        LD D,A        LD E,(IX+#1A);DE=ДЛИHA СMEHЫ ФAЙЛА        CALL Z68ED ;сдвинуть указатель в файле (bhl) на de байт и проверить, что не вышли за границу файла?        LD D,(IX+#1D)        LD E,(IX+#1C);DE=ДATA ПOCЛEДHEЙ MOДИФИKAЦИИ        CALL Z68ED ;сдвинуть указатель в файле (bhl) на de байт и проверить, что не вышли за границу файла?        LD D,(IX+#13)        LD E,(IX+#12)        LD A,(IX+#14);A,DE=ДЛИHA CЖATOГO ФAЙЛA        CALL Z68EE ;сдвинуть указатель в файле (bhl) на ade байт и проверить, что не вышли за границу файла?        LD A,(IX+#16)        OR (IX+#17)        OR (IX+#18)        OR (IX+#19);ИCXOДHAЯ ДЛИHA ФAЙЛA        EXA         PUSH IX        POP HL        LD BC,7        ADD HL,BC        RES 7,(IX+7);METOД CЖATИЯ, CTAPШИЙ БAЙT        LD B,#18-3Z6825   LD A,(HL)        DEC H        SUB (HL) ;TODO что с чем сравниваем?        JR NZ,ERR_Z1    